import { describe, it, expect, vi } from 'vitest';
import { TodoStore } from './todoStore';

vi.mock('../utils/storage', () => ({
  loadTasks: () => [],
  saveTasks: vi.fn(),
  loadFilter: () => 'all',
  saveFilter: vi.fn()
}));

describe('TodoStore.search', () => {
  it('returns tasks matching the query', () => {
    const store = new TodoStore();
    store.add('buy milk');
    store.add('walk the dog');
    expect(store.search('milk')).toHaveLength(1);
  });
});

